cypress_script:
describe('Tool Shop Product Catalogue', () => {
  it('should search for tools and display results', () => {
    cy.visit('https://practicesoftwaretesting.com/');
    cy.get('input[data-test="search-query"]').type('hammer');
    cy.get('button[data-test="search-submit"]').click();
    cy.url().should('include', 'search=hammer');
    cy.get('div[data-test="notification-bar"]').should('be.visible');
  });

  it('should not display results for non-existent tools', () => {
    cy.visit('https://practicesoftwaretesting.com/');
    cy.get('input[data-test="search-query"]').type('nonexistenttool');
    cy.get('button[data-test="search-submit"]').click();
    cy.url().should('include', 'search=nonexistenttool');
    cy.get('div[data-test="notification-bar"]').should('be.visible');
  });
});

playwright_script:
test.describe('Tool Shop Product Catalogue', () => {
  test('should search for tools and display results', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/');
    await page.fill('input[data-test="search-query"]', 'hammer');
    await page.click('button[data-test="search-submit"]');
    await page.waitForURL(/.*search=hammer/);
    await page.locator('div[data-test="notification-bar"]').isVisible();
  });

  test('should not display results for non-existent tools', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/');
    await page.fill('input[data-test="search-query"]', 'nonexistenttool');
    await page.click('button[data-test="search-submit"]');
    await page.waitForURL(/.*search=nonexistenttool/);
    await page.locator('div[data-test="notification-bar"]').isVisible();
  });
});
